roles.source:
@startuml
layout landscape
interface Observer {
  + update()
}
class Model {
  + attach(observer)
  + notify()
  + getData()
  + setData(value)
}
class View {
  + update()
  + display()
}
class Controller {
  + handleEvent(event)
}
Model --> "*" Observer : notifies
View ..|> Observer
Controller ..|> Observer
View --> "1" Model : reads
Controller --> "1" Model : changes
Controller --> "1" View : adjusts
@enduml

