@startuml
layout landscape
interface Observer {
  + update()
}
class Dataset {
  + attach(observer)
  + detach(observer)
  + notify()
  + setMinutes(category, minutes)
  + rows()
}
class View {
  + initialize()
  + update()
  + highlight(category)
}
class Controller {
  + handleEvent(event)
  + update()
}
Dataset --> "*" Observer : notifies
View ..|> Observer
Controller ..|> Observer
View --> "1" Dataset : reads
Controller --> "1" Dataset : changes
View "1" -- "1" Controller : pairs with
@enduml

